"use strict";
module.exports = "/* Behavior Tree Editor Styles */\r\n\r\n.bt-action-list {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: var(--editor-spacing-sm, 8px);\r\n}\r\n\r\n.bt-action-item {\r\n    padding: var(--editor-spacing-sm, 8px);\r\n    border: 1px solid var(--editor-border-color, #333);\r\n    border-radius: var(--editor-border-radius-sm, 4px);\r\n    background: var(--editor-bg-secondary, #1a1a1a);\r\n    cursor: grab;\r\n    transition: all 0.2s;\r\n}\r\n\r\n.bt-action-item:hover {\r\n    background: var(--editor-bg-hover, #252525);\r\n    border-color: var(--editor-primary, #6366f1);\r\n}\r\n\r\n.bt-action-item__title {\r\n    font-weight: 600;\r\n    color: var(--editor-text-primary, #fff);\r\n    margin-bottom: 4px;\r\n}\r\n\r\n.bt-action-item__priority {\r\n    font-size: 12px;\r\n    color: var(--editor-text-muted, #888);\r\n}\r\n\r\n.bt-node-types {\r\n    display: grid;\r\n    grid-template-columns: 1fr 1fr;\r\n    gap: var(--editor-spacing-sm, 8px);\r\n}\r\n\r\n.bt-node-btn {\r\n    padding: var(--editor-spacing-sm, 8px);\r\n}\r\n\r\n.bt-canvas-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    padding: var(--editor-spacing-md, 16px);\r\n    border-bottom: 1px solid var(--editor-border-color, #333);\r\n}\r\n\r\n.bt-canvas-header h2 {\r\n    margin: 0;\r\n    font-size: 18px;\r\n    color: var(--editor-text-primary, #fff);\r\n}\r\n\r\n.bt-canvas-controls {\r\n    display: flex;\r\n    gap: var(--editor-spacing-xs, 4px);\r\n}\r\n\r\n.bt-tree-canvas {\r\n    flex: 1;\r\n    position: relative;\r\n    overflow: auto;\r\n    background: var(--editor-bg-primary, #0a0a0a);\r\n    background-image: \r\n        linear-gradient(rgba(255,255,255,0.05) 1px, transparent 1px),\r\n        linear-gradient(90deg, rgba(255,255,255,0.05) 1px, transparent 1px);\r\n    background-size: 20px 20px;\r\n}\r\n\r\n.bt-node {\r\n    position: absolute;\r\n    min-width: 150px;\r\n    padding: var(--editor-spacing-md, 16px);\r\n    border: 2px solid var(--editor-border-color, #333);\r\n    border-radius: var(--editor-border-radius-md, 8px);\r\n    background: var(--editor-bg-secondary, #1a1a1a);\r\n    cursor: move;\r\n    transition: all 0.2s;\r\n}\r\n\r\n.bt-node:hover {\r\n    border-color: var(--editor-primary, #6366f1);\r\n    box-shadow: 0 4px 12px rgba(99, 102, 241, 0.3);\r\n}\r\n\r\n.bt-node--selected {\r\n    border-color: var(--editor-primary, #6366f1);\r\n    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2);\r\n}\r\n\r\n.bt-node--selector {\r\n    border-color: #10b981;\r\n}\r\n\r\n.bt-node--sequence {\r\n    border-color: #f59e0b;\r\n}\r\n\r\n.bt-node--condition {\r\n    border-color: #3b82f6;\r\n}\r\n\r\n.bt-node--action {\r\n    border-color: #ef4444;\r\n}\r\n\r\n.bt-node__header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    margin-bottom: var(--editor-spacing-sm, 8px);\r\n}\r\n\r\n.bt-node__type {\r\n    font-size: 10px;\r\n    text-transform: uppercase;\r\n    letter-spacing: 0.5px;\r\n    color: var(--editor-text-muted, #888);\r\n}\r\n\r\n.bt-node__title {\r\n    font-weight: 600;\r\n    color: var(--editor-text-primary, #fff);\r\n}\r\n\r\n.bt-node__actions {\r\n    display: flex;\r\n    gap: 4px;\r\n}\r\n\r\n.bt-node__btn {\r\n    width: 20px;\r\n    height: 20px;\r\n    padding: 0;\r\n    font-size: 14px;\r\n    border: none;\r\n    background: var(--editor-bg-hover, #252525);\r\n    color: var(--editor-text-primary, #fff);\r\n    border-radius: 3px;\r\n    cursor: pointer;\r\n}\r\n\r\n.bt-node__btn:hover {\r\n    background: var(--editor-primary, #6366f1);\r\n}\r\n\r\n.bt-connection {\r\n    position: absolute;\r\n    pointer-events: none;\r\n}\r\n\r\n.bt-connection-line {\r\n    stroke: var(--editor-border-color, #333);\r\n    stroke-width: 2;\r\n    fill: none;\r\n}\r\n\r\n.bt-connection-line--active {\r\n    stroke: var(--editor-primary, #6366f1);\r\n}\r\n\r\n.bt-node-properties {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: var(--editor-spacing-sm, 8px);\r\n}\r\n\r\n.bt-property {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 4px;\r\n}\r\n\r\n.bt-property__label {\r\n    font-size: 12px;\r\n    font-weight: 600;\r\n    color: var(--editor-text-muted, #888);\r\n}\r\n\r\n.bt-property__input {\r\n    padding: var(--editor-spacing-sm, 8px);\r\n    background: var(--editor-bg-primary, #0a0a0a);\r\n    border: 1px solid var(--editor-border-color, #333);\r\n    border-radius: var(--editor-border-radius-sm, 4px);\r\n    color: var(--editor-text-primary, #fff);\r\n    font-family: inherit;\r\n}\r\n\r\n.bt-json-textarea {\r\n    min-height: 300px;\r\n    font-family: 'Courier New', monospace;\r\n    font-size: 12px;\r\n    resize: vertical;\r\n}\r\n\r\n.bt-validation-output {\r\n    position: absolute;\r\n    bottom: 0;\r\n    left: 0;\r\n    right: 0;\r\n    max-height: 150px;\r\n    overflow-y: auto;\r\n    background: var(--editor-bg-secondary, #1a1a1a);\r\n    border-top: 1px solid var(--editor-border-color, #333);\r\n    padding: var(--editor-spacing-md, 16px);\r\n    display: none;\r\n}\r\n\r\n.bt-validation-output--visible {\r\n    display: block;\r\n}\r\n\r\n.bt-validation-error {\r\n    color: #ef4444;\r\n    margin: 4px 0;\r\n}\r\n\r\n.bt-validation-success {\r\n    color: #10b981;\r\n    margin: 4px 0;\r\n}\r\n\r\n/* Simulation Styles */\r\n.bt-simulation-vars {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 8px;\r\n}\r\n\r\n.bt-sim-var {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 4px;\r\n}\r\n\r\n.bt-sim-var__label {\r\n    font-size: 11px;\r\n    color: #aaa;\r\n    font-weight: 500;\r\n}\r\n\r\n.bt-sim-var input[type=\"checkbox\"] {\r\n    width: 16px;\r\n    height: 16px;\r\n    cursor: pointer;\r\n}\r\n\r\n.bt-sim-var input[type=\"text\"],\r\n.bt-sim-var input[type=\"number\"] {\r\n    padding: 4px 8px;\r\n    background: #0a0a0a;\r\n    border: 1px solid #333;\r\n    border-radius: 4px;\r\n    color: #fff;\r\n    font-size: 12px;\r\n}\r\n\r\n.bt-sim-result {\r\n    color: #fff;\r\n}\r\n\r\n.bt-sim-result__action {\r\n    font-weight: 600;\r\n    color: #6366f1;\r\n}\r\n\r\n/* Active/Inactive node highlighting */\r\n.bt-node-active {\r\n    background: rgba(230, 226, 7, 0.747) !important;\r\n    font-weight: 700;\r\n}\r\n\r\n.bt-node-inactive {\r\n    opacity: 0.4;\r\n}";

