module.exports = "/* =============================================================================\r\n   SCRIPT EDITOR - MODULE-SPECIFIC STYLES\r\n   ============================================================================= */\r\n\r\n/* Main container - use viewport height */\r\n#script-editor-container {\r\n    display: flex;\r\n    flex-direction: row;\r\n    height: calc(100vh - 100px);\r\n    min-height: calc(100vh - 100px);\r\n}\r\n\r\n#script-editor-container .editor-module__canvas-area {\r\n    flex: 1;\r\n    display: flex;\r\n    flex-direction: column;\r\n    height: 100%;\r\n}\r\n\r\n/* Code container */\r\n.script-editor__code-container {\r\n    position: relative;\r\n    flex: 1;\r\n    display: flex;\r\n    flex-direction: column;\r\n    height: 100%;\r\n    width: 100%;\r\n}\r\n\r\n/* Monaco editor container */\r\n#script-editor {\r\n    flex: 1;\r\n    width: 100%;\r\n    height: 100%;\r\n    overflow: hidden;\r\n    border: 1px solid #3c3c3c;\r\n    border-radius: 4px;\r\n}\r\n\r\n/* Ensure Monaco editor fills its container */\r\n#script-editor-container .monaco-editor,\r\n#script-editor-container .monaco-editor .overflow-guard {\r\n    width: 100% !important;\r\n    height: 100% !important;\r\n}\r\n";

