module.exports = "<div id=\"level-editor-container\" class=\"editor-module\">\r\n   <div class=\"editor-module__sidebar editor-module__sidebar--left\">\r\n     <div class=\"te-header\">\r\n       <div class=\"te-header__row\">\r\n         <label class=\"te-header__label\">Mode:</label>\r\n         <select id=\"te-mode-select\" class=\"te-header__select\">\r\n           <option value=\"terrains\">Terrains</option>\r\n           <option value=\"heights\">Heights</option>\r\n           <option value=\"ramps\">Ramps</option>\r\n           <option value=\"entities\">Entities</option>\r\n         </select>\r\n       </div>\r\n       <div id=\"te-tool-section\">\r\n         <div class=\"te-header__row\">\r\n           <label class=\"te-header__label\">Tool:</label>\r\n           <div class=\"terrain-editor__tool-buttons\">\r\n             <button id=\"globalBrushBtn\" class=\"editor-module__btn editor-module__btn--small editor-module__btn--active\">Brush</button>\r\n             <button id=\"globalFillBtn\" class=\"editor-module__btn editor-module__btn--small\">Fill</button>\r\n           </div>\r\n         </div>\r\n         <div class=\"te-header__row\">\r\n           <label for=\"globalBrushSize\" class=\"te-header__label\">Brush:</label>\r\n           <input type=\"range\" id=\"globalBrushSize\" class=\"editor-module__slider\" value=\"1\" step=\"1\" min=\"1\" max=\"5\">\r\n           <span id=\"globalBrushSizeValue\" class=\"editor-module__value-display\">1</span>\r\n         </div>\r\n       </div>\r\n       <button id=\"saveMapBtn\" class=\"editor-module__btn editor-module__btn--success\" style=\"width: 100%; margin-top: 8px;\">Save Map</button>\r\n     </div>\r\n\r\n     <div class=\"editor-module__scroll-y\">\r\n       <!-- TERRAINS PANEL -->\r\n       <div id=\"terrainsPanel\" class=\"te-panel\">\r\n         <div class=\"te-panel__section\">\r\n           <h3 class=\"te-panel__title\">Map Settings</h3>\r\n           <div class=\"te-panel__row\">\r\n             <label for=\"terrainMapSize\" class=\"te-header__label\">Size:</label>\r\n             <input type=\"number\" id=\"terrainMapSize\" class=\"te-input--small\" value=\"48\" step=\"1\" min=\"1\">\r\n           </div>\r\n           <div class=\"te-panel__row\">\r\n             <label for=\"extensionTerrainType\" class=\"te-header__label\">Surround:</label>\r\n             <select id=\"extensionTerrainType\" class=\"te-select\"></select>\r\n           </div>\r\n         </div>\r\n         <div class=\"te-panel__section\">\r\n           <h3 class=\"te-panel__title\">Terrain Types</h3>\r\n           <div class=\"terrain-editor__terrain-list te-terrain-list\">\r\n             <!-- Terrain items will be dynamically populated here -->\r\n           </div>\r\n         </div>\r\n       </div>\r\n\r\n       <!-- RAMPS PANEL -->\r\n       <div id=\"rampsPanel\" class=\"te-panel\" style=\"display: none;\">\r\n         <div class=\"te-panel__section\">\r\n           <h3 class=\"te-panel__title\">Ramps <span id=\"rampCount\" class=\"te-badge\">0</span></h3>\r\n           <p class=\"te-hint\">Click tiles to place/remove ramps</p>\r\n           <button class=\"editor-module__btn editor-module__btn--small editor-module__btn--danger\" id=\"clear-all-ramps-btn\">Clear All</button>\r\n         </div>\r\n       </div>\r\n\r\n       <!-- HEIGHTS PANEL -->\r\n       <div id=\"heightsPanel\" class=\"te-panel\" style=\"display: none;\">\r\n         <div class=\"te-panel__section\">\r\n           <h3 class=\"te-panel__title\">Height Level</h3>\r\n           <div class=\"te-panel__row\">\r\n             <label for=\"heightLevel\" class=\"te-header__label\">Level:</label>\r\n             <input type=\"number\" id=\"heightLevel\" class=\"te-input--small\" value=\"0\" step=\"1\" min=\"0\" max=\"10\">\r\n           </div>\r\n           <div class=\"terrain-editor__height-levels\" id=\"heightLevelButtons\">\r\n             <!-- Height level buttons will be dynamically populated here -->\r\n           </div>\r\n         </div>\r\n       </div>\r\n\r\n       <!-- ENTITIES PANEL -->\r\n       <div id=\"placementsPanel\" class=\"te-panel\" style=\"display: none;\">\r\n         <div class=\"te-panel__section te-panel__section--fixed\">\r\n           <h3 class=\"te-panel__title\">Add Entity</h3>\r\n           <select id=\"te-collection-select\" class=\"te-select\"></select>\r\n           <div id=\"te-spawn-type-grid\" class=\"te-grid--spawn\">\r\n             <!-- Spawn types will be populated here as icon grid -->\r\n           </div>\r\n         </div>\r\n         <div class=\"te-panel__section te-panel__section--flex\">\r\n           <h3 class=\"te-panel__title\">Placed Entities <span id=\"te-entity-count\" class=\"te-badge\"></span></h3>\r\n           <div id=\"te-entity-hierarchy\" class=\"te-list--compact\">\r\n             <!-- Placed entities will be populated here -->\r\n           </div>\r\n         </div>\r\n       </div>\r\n     </div>\r\n   </div>\r\n\r\n   <div class=\"editor-module__canvas-area editor-module__grid-background\">\r\n     <!-- Canvas Toolbar -->\r\n     <div class=\"editor-module__canvas-toolbar\">\r\n       <div class=\"editor-module__toolbar-group\">\r\n         <button id=\"te-translate-tool\" class=\"editor-module__btn editor-module__btn--small editor-module__btn--active\" title=\"Move (W)\">\r\n           <span>Move</span>\r\n         </button>\r\n         <button id=\"te-rotate-tool\" class=\"editor-module__btn editor-module__btn--small\" title=\"Rotate (E)\">\r\n           <span>Rotate</span>\r\n         </button>\r\n         <button id=\"te-scale-tool\" class=\"editor-module__btn editor-module__btn--small\" title=\"Scale (R)\">\r\n           <span>Scale</span>\r\n         </button>\r\n       </div>\r\n       <div class=\"editor-module__toolbar-separator\"></div>\r\n       <div class=\"editor-module__toolbar-group\">\r\n         <button id=\"te-camera-toggle\" class=\"editor-module__btn editor-module__btn--small\" title=\"Toggle Camera Mode\">\r\n           <span>Scene Cam</span>\r\n         </button>\r\n         <button id=\"te-camera-rotate-left\" class=\"editor-module__btn editor-module__btn--small\" title=\"Rotate Camera Left\" style=\"display: none;\">\r\n           <span>&#9664;</span>\r\n         </button>\r\n         <button id=\"te-camera-rotate-right\" class=\"editor-module__btn editor-module__btn--small\" title=\"Rotate Camera Right\" style=\"display: none;\">\r\n           <span>&#9654;</span>\r\n         </button>\r\n       </div>\r\n     </div>\r\n\r\n     <canvas id=\"grid\" class=\"editor-module__canvas\"></canvas>\r\n\r\n     <div class=\"editor-module__status-bar\">\r\n       Cursor: x: 0, y: 0 | Zoom: 100% | Selected: Grass\r\n     </div>\r\n   </div>\r\n\r\n   <!-- Right Sidebar - Inspector (hidden when no entity selected) -->\r\n   <div id=\"te-inspector-sidebar\" class=\"editor-module__sidebar editor-module__sidebar--right\" style=\"display: none;\">\r\n     <div class=\"te-panel__section\">\r\n       <h3 class=\"te-panel__title\">Inspector</h3>\r\n       <div id=\"te-inspector-content\">\r\n         <!-- Inspector content dynamically populated -->\r\n       </div>\r\n       <button id=\"te-remove-entity-btn\" class=\"editor-module__btn editor-module__btn--danger editor-module__btn--small\" style=\"margin-top: 8px;\">Remove Entity</button>\r\n     </div>\r\n   </div>\r\n </div>\r\n";

